// Demote to a unit test of the GST calculator.
// Runs in <5ms. No browser, no login, no flake.
import { calculateGst } from '../src/lib/gst';

describe('calculateGst', () => {
  test('charges IGST for an interstate cart', () => {
    const result = calculateGst({
      items: [{ price: 1000, hsn: '9983' }, { price: 1500, hsn: '9983' }, { price: 500, hsn: '9983' }],
      sellerState: 'MH',
      buyerState: 'KA',
    });
    expect(result).toEqual({ cgst: 0, sgst: 0, igst: 540 });
  });

  test('splits to CGST + SGST for an intrastate cart', () => {
    const result = calculateGst({
      items: [{ price: 3000, hsn: '9983' }],
      sellerState: 'KA',
      buyerState: 'KA',
    });
    expect(result).toEqual({ cgst: 270, sgst: 270, igst: 0 });
  });
});

